32	/* --- Shared between the cores (DESIGN-NOTES.md, M5, "Two cores") -----
33	 * Core 0 changes the voices only between blocks, and core 1 renders its
34	 * own voices only during one: core 0 posts a block by raising job_seq,
35	 * core 1 answers with job_done. Each shared load follows csync, and the
36	 * sequence numbers change under the lock, the SDK's way (HW-65). */
37	static struct fm_voice voice[FM_VOICES];
38	static s32 mix[2][AUDIO_FRAMES];
39	static s32 scratch[2][FM_OPS + 1][AUDIO_FRAMES];
