42	
43	/* HW-65: test-and-set the byte until it was clear, csync around. */
44	static void lock(volatile u8 *b)
45	{
46	    __asm__ volatile("csync\n"
47	                     "1:\n\t"
48	                     "testset b[%0]\n\t"
49	                     "ifeq goto 1b\n\t"
50	                     "csync" : : "r"(b) : "memory");
51	}
52	
53	static void unlock(volatile u8 *b)
54	{
55	    __asm__ volatile("csync" : : : "memory");
56	    *b = 0;
57	}
58	
59	static u32 shared(volatile u32 *p)
60	{
61	    __asm__ volatile("csync" : : : "memory");
62	    return *p;
63	}
64	
65	static void publish(volatile u32 *p, u32 v)
66	{
67	    lock(&job_lock);
68	    *p = v;
69	    unlock(&job_lock);
70	}
71	
72	/* Core 1: renders the odd voices whenever core 0 posts a block. Its loop
73	 * changes nothing while it waits, so fwtest ends its turns early
74	 * (HW-64). */
75	void fm_core1_main(void)
76	{
77	    u32 seen = 0;
78	
79	    publish(&core1_running, 1);
80	    sb_fm.core1 = 1;
81	    for (;;) {
82	        u32 s = shared(&job_seq), n, v;
83	        if (s == seen)
84	            continue;
85	        seen = s;
86	        for (n = 0; n < AUDIO_FRAMES; n++)
87	            mix[1][n] = 0;
