134	static struct patch patches[FM_PROGRAMS];
135	/* The user slots' patches as bytes, and which slots hold one (since M7). */
136	static u8 user_raw[FM_USER_SLOTS][FM_PATCH_BYTES];
137	/* The program playing now as bytes, with the operator view's edits, and
138	 * whether there are any (M8a part 3). */
139	static u8 edit_raw[FM_PATCH_BYTES];
140	static u32 edited;
