151	static u32 sounding;        /* voices not idle */
152	static int octave, mono_stack[16];
153	static u32 mono_held;
154	static s32 master;
155	static int key_note[27];   /* the note each key started; -1: none */
156	/* The controls this block: KNOB1 to KNOB4 (DESIGN-NOTES.md, M5, "The
157	 * controls"). */
158	static s32 pitch_knob, depth_att;
159	static u32 glide_code;
160	static int feedback_knob;
161	
162	/* Who holds each note (M6a): the panel's keys, MIDI, the sustain pedal.
163	 * The engine hears a note's off only when none holds it any more. */
164	#define HOLD_PANEL 1u
165	#define HOLD_MIDI  2u
166	#define HOLD_PEDAL 4u
167	static u8 hold[128];
168	volatile u32 fm_midi_notes[4];   /* notes MIDI or the pedal holds, for the screen */
169	
170	/* MIDI's controls: the pitch bend and vibrato (1 / 4096 semitone), the
171	 * levels (0 to 127), the pedal, the four knobs' offsets (in their own
172	 * steps), and the parameter number data entry changes (RPN; 0x3FFF:
173	 * none). */
174	static s32 bend, vibrato;
175	static u32 mod_wheel, volume = 127, expression = 127, pedal;
176	static int midi_knob[4];
177	/* The panel's KNOB1 to KNOB4 as the engine last took them: frozen while
178	 * local control is off (M6b). The program the panel's PRESETS last chose. */
179	static int panel_knob[4];
180	/* Since M8a: KNOB1 to KNOB4's positions as the patch view's controls,
181	 * moved only by turns there and held to the span (so turning back from
182	 * past an end answers at once); the other screens' turns edit instead. */
183	static int knob_pos[4];
184	/* midi_settings.knobs as knobs() last took it (M8a): 0 the macros. */
185	static u32 knobs_mode;
186	static u32 panel_program;
187	static u32 lfo_phase, rpn = 0x3FFFu;
188	
189	#define OCTAVES   2
190	#define SEMITONE  4096
191	
192	/* The per-block steps of a stage taking 1 ms over its whole range
193	 * (fm.h's time codes), computed offline for 64 frames at 24 MHz / 544:
194	 * 16 octaves of attenuation (2^-16), a gain of 1 (2^-30), the pitch
195	 * envelope's 254 levels (2^-16). */
196	#define STEP_ATT  1521134u
197	#define STEP_LIN  1557641473u
198	#define STEP_LVL  24148006u
199	/* A fixed frequency's phase step, a quarter hertz's, in 2^-16. */
200	#define FIXED_Q16 1595024868u
201	/* A block, in milliseconds, in 2^-16: 64 x 544 / 24 000 x 65536. */
202	#define BLOCK_MS_Q16 95072u
203	#define GAIN_ONE  (1 << 30)
204	/* The vibrato's phase step a block: 5.5 Hz at 44 117.647 / 64 blocks a
205	 * second, in 2^-32 of a cycle. */
206	#define LFO_INC   34268112u
207	
208	/* A stage's step a block: 2^(-code / 8) of the 1 ms one. */
209	static s32 step_of(u32 code, u32 full)
210	{
211	    return (s32)(((u64)full * (u32)fm_exp2_neg((s32)(code << 13))) >> 30);
212	}
213	
214	/* How many blocks a time code is: 2^(code / 8) ms over a block's. */
215	static u32 blocks_of(u32 code)
216	{
217	    u64 ms_q30 = (u64)fm_exp2_frac((code & 7u) << 13) << (code >> 3);
218	    u32 n = (u32)(ms_q30 >> 14) / BLOCK_MS_Q16;
219	
220	    return n ? n : 1;
221	}
222	
223	static int signed8(u8 x)
224	{
225	    return x > 127 ? (int)x - 256 : (int)x;
226	}
227	
228	static void patch_parse(struct patch *p, const u8 *b)
229	{
230	    u32 i, k;
231	
232	    p->algorithm = b[FMP_ALGORITHM] - 1u;
233	    p->feedback = b[FMP_FEEDBACK];
234	    p->mono = b[FMP_FLAGS] & 1u;
235	    p->glide = b[FMP_GLIDE];
236	    p->transpose = signed8(b[FMP_TRANSPOSE]);
237	    p->pitch_depth = signed8(b[FMP_PITCH_DEPTH]);
238	    for (i = 0; i < 3; i++)
239	        p->pitch_step[i] = step_of(b[FMP_PITCH_RATE + i], STEP_LVL);
240	    for (i = 0; i < 4; i++)
241	        p->pitch_level[i] = signed8(b[FMP_PITCH_LEVEL + i]) * 65536;
242	    for (i = 0; i < FM_OPS; i++) {
243	        const u8 *o = b + FM_OP_OFFSET + FM_OP_BYTES * i;
244	        u32 f = (u32)o[FMO_FREQ] | (u32)o[FMO_FREQ + 1] << 8;
245	        int cents = signed8(o[FMO_DETUNE]);
246	        p->op[i].off = o[FMO_LEVEL] == 0;
247	        p->op[i].fixed = o[FMO_MODE] == 1;
248	        p->op[i].freq = p->op[i].fixed ? (u32)(((u64)f * FIXED_Q16) >> 16) : f;
249	        /* 2^(cents / 1200), in 2^-30. */
250	        p->op[i].detune = cents >= 0 ? (s32)fm_exp2_frac((u32)(cents * 65536 / 1200))
251	                                     : fm_exp2_neg(-cents * 65536 / 1200);
252	        p->op[i].level_att = (s32)(127u - o[FMO_LEVEL]) << 13;
253	        p->op[i].velocity = o[FMO_VELOCITY];
254	        p->op[i].step[0] = step_of(o[FMO_RATE], STEP_LIN);
255	        for (k = 1; k < 4; k++)
256	            p->op[i].step[k] = step_of(o[FMO_RATE + k], STEP_ATT);
257	        for (k = 0; k < 3; k++)
258	            p->op[i].target[k] = (s32)(127u - o[FMO_ENV_LEVEL + k]) << 13;
259	    }
260	}
261	
262	int fm_patch_valid(const u8 *b)
263	{
264	    u32 i, k;
265	
266	    if (b[FMP_MAGIC0] != 'F' || b[FMP_MAGIC1] != 'M' || b[FMP_VERSION] != FM_PATCH_VERSION
267	        || b[FMP_LENGTH] != FM_PATCH_BYTES)
268	        return 0;
269	    for (i = FMP_NAME; i < FMP_NAME + 12; i++)
270	        if (b[i] && (b[i] < 32 || b[i] > 126))
271	            return 0;
272	    if (b[FMP_ALGORITHM] < 1 || b[FMP_ALGORITHM] > FM_ALGORITHMS || b[FMP_FEEDBACK] > 7
273	        || b[FMP_FLAGS] > 1 || b[FMP_GLIDE] > 127)
274	        return 0;
275	    if (signed8(b[FMP_TRANSPOSE]) < -24 || signed8(b[FMP_TRANSPOSE]) > 24
276	        || signed8(b[FMP_PITCH_DEPTH]) < -48 || signed8(b[FMP_PITCH_DEPTH]) > 48)
277	        return 0;
278	    for (i = 0; i < 3; i++)
279	        if (b[FMP_PITCH_RATE + i] > 127)
280	            return 0;
281	    for (i = 0; i < 4; i++)
282	        if (signed8(b[FMP_PITCH_LEVEL + i]) < -127)
283	            return 0;
284	    for (i = 29; i < 32; i++)
285	        if (b[i])
286	            return 0;
287	    for (i = 0; i < FM_OPS; i++) {
288	        const u8 *o = b + FM_OP_OFFSET + FM_OP_BYTES * i;
289	        if (o[FMO_MODE] > 1 || signed8(o[FMO_DETUNE]) < -100 || signed8(o[FMO_DETUNE]) > 100
290	            || o[FMO_LEVEL] > 127 || o[FMO_VELOCITY] > 7)
291	            return 0;
292	        for (k = FMO_RATE; k < FM_OP_BYTES; k++)
293	            if (o[k] > 127)
294	                return 0;
295	    }
296	    return fm_patch_sum(b) == ((u32)b[FM_SUM_OFFSET] | (u32)b[FM_SUM_OFFSET + 1] << 8);
297	}
298	
299	/* Fletcher's 16-bit check sum of the bytes before it. */
300	u32 fm_patch_sum(const u8 *b)
301	{
302	    u32 a = 0, c = 0, i;
303	
304	    for (i = 0; i < FM_SUM_OFFSET; i++) {
305	        a = (a + b[i]) % 255u;
306	        c = (c + a) % 255u;
307	    }
308	    return c << 8 | a;
309	}
310	
311	/* --- The macros (M8a; docs/M8-PROPOSAL.md, docs/DESIGN-NOTES.md) ------
312	 * KNOB1 to KNOB4 on the patch view, unless the setting "Knobs: direct"
313	 * (midi_settings.knobs) gives them M5's controls. Each moves several of
314	 * the patch's values at once as an offset over the stored patch, so at 0
315	 * the patch sounds exactly as stored, and turning it back returns there:
316	 * - BRIGHT: every modulator's level (M5's KNOB3, renamed);
317	 * - COLOR: the modulators' ratios, from whole numbers (below 0, each
318	 *   moved toward its nearest whole number, or a half) to inharmonic (above
319	 *   0, each multiplied by up to the square root of 2, the same sweep on
320	 *   every patch), and feedback up to 3 steps more at the metallic end;
321	 * - SHAPE: the carriers' envelopes, from a pluck (below 0: a fast attack,
322	 *   a short decay, a quick release, the held level falling away) to a pad
323	 *   (above 0: a slow attack, full sustain, a long release);
324	 * - MOTION: vibrato (5.5 Hz, up to half a semitone) and a detune spread
325	 *   across the carriers (the first in tune, the others up to 12 cents
326	 *   above and below it in turn).
327	 * The operators' values with COLOR and SHAPE applied are worked out once
328	 * a change (shape_ops), not each note or block. */
329	#define MACRO_BRIGHT 0
330	#define MACRO_COLOR  1

