453	    const struct patch *p = &patches[patch_now];
454	    u32 i, k, fresh = v->state != VOICE_ON, carriers = 0;
455	    /* Velocity: up to 8 octaves (48 dB) less at velocity 0, for a
456	     * sensitivity of 7, in proportion below (DESIGN-NOTES.md, M5). */
