536	/* Poly: the same note again takes its own voice back; else a free voice,
537	 * on the core with fewer sounding; else the quietest released voice;
538	 * else the oldest. A voice taken while it sounds fades out over one block
539	 * first, and the new note starts the block after (DESIGN-NOTES.md, M5,
540	 * "Voices"). */
541	static void poly_on(int note, u32 velocity)
542	{
543	    u32 n, pick = FM_VOICES, load[2] = { 0, 0 };
544	
545	    for (n = 0; n < FM_VOICES; n++)
546	        if (voice[n].state == VOICE_ON) {
547	            load[n & 1]++;
548	            if (ctl[n].note == note && ctl[n].next < 0 && !voice[n].fade)
549	                pick = n;
550	        }
551	    if (pick < FM_VOICES) {
552	        voice_start(pick, note, velocity);
553	        return;
554	    }
555	    for (n = 0; n < FM_VOICES; n++) {
556	        if (voice[n].state == VOICE_ON || (!two_cores && (n & 1)))
557	            continue;
558	        if (pick == FM_VOICES || (two_cores && load[n & 1] < load[pick & 1]))
559	            pick = n;
560	    }
561	    if (pick < FM_VOICES) {
562	        voice_start(pick, note, velocity);
563	        return;
564	    }
