990	/* --- The operator view's editing (M8a part 3) -------------------------
991	 * KNOB1 to KNOB4 on EDIT edit the selected operator of the program
992	 * playing now, page by page (SELECT): ratio or frequency, level, detune,
993	 * velocity; mode, coarse, fine; the envelope's three levels. */
994	static const u16 ratios[] = {
995	    128, 256, 512, 768, 1024, 1280, 1536, 1792, 2048, 2304, 2560, 2816, 3072, 3328, 3584, 3840, 4096,
996	};
997	#define RATIOS (sizeof ratios / sizeof ratios[0])
998	
999	/* The next whole ratio (or a half) up or down from f (x 256). */
1000	static u32 ratio_step(u32 f, int d)
1001	{
1002	    u32 i;
1003	
1004	    if (d > 0) {
1005	        for (i = 0; i < RATIOS; i++)
1006	            if (ratios[i] > f)
1007	                return ratios[i];
1008	        return f;
1009	    }
1010	    for (i = RATIOS; i--;)
1011	        if (ratios[i] < f)
1012	            return ratios[i];
1013	    return f;
1014	}
