1016	/* After an edit: the copy's check sum, parsed again. */
1017	static void edit_done(void)
1018	{
1019	    u32 sum = fm_patch_sum(edit_raw);
1020	
1021	    edit_raw[FM_SUM_OFFSET] = (u8)sum;
1022	    edit_raw[FM_SUM_OFFSET + 1] = (u8)(sum >> 8);
1023	    patch_parse(&patches[patch_now], edit_raw);
1024	    edited = 1;
1025	    shaped_patch = 0xFFFFFFFFu;
1026	}
