1028	static void edit_op(u32 knob, int d)
1029	{
1030	    u8 *o = edit_raw + FM_OP_OFFSET + FM_OP_BYTES * fm_ui.op;
1031	    u32 f = (u32)o[FMO_FREQ] | (u32)o[FMO_FREQ + 1] << 8;
1032	
1033	    switch (fm_ui.page * 4u + knob) {
1034	    case 0:   /* RATIO, or the fixed frequency a semitone a detent */
1035	        if (o[FMO_MODE])
1036	            f = d > 0 ? (f * 69433u) >> 16 : (f * 61858u) >> 16;
1037	        else
1038	            f = ratio_step(f, d);
1039	        break;
1040	    case 1:
1041	        o[FMO_LEVEL] = (u8)clamp(o[FMO_LEVEL] + d, 0, 127);
1042	        break;
1043	    case 2:
1044	        o[FMO_DETUNE] = (u8)clamp(signed8(o[FMO_DETUNE]) + d, -100, 100);
1045	        break;
1046	    case 3:
1047	        o[FMO_VELOCITY] = (u8)clamp(o[FMO_VELOCITY] + d, 0, 7);
1048	        break;
1049	    case 4:   /* MODE: ratio 1, or fixed at 440 Hz */
1050	        o[FMO_MODE] = d > 0;
1051	        f = d > 0 ? 1760u : 256u;
1052	        break;
1053	    case 5:   /* COARSE: a whole ratio, or an octave */
1054	        if (o[FMO_MODE])
1055	            f = d > 0 ? f * 2u : f / 2u;
1056	        else
1057	            f = (u32)clamp((int)f + 256 * d, 32, 65535);
1058	        break;
1059	    case 6:   /* FINE: 1/256 of a ratio, or 1 Hz */
1060	        f = (u32)clamp((int)f + (o[FMO_MODE] ? 4 * d : d), 1, 65535);
1061	        break;
1062	    case 8:
1063	    case 9:
1064	    case 10:
1065	        o[FMO_ENV_LEVEL + knob] = (u8)clamp(o[FMO_ENV_LEVEL + knob] + d, 0, 127);
1066	        break;
1067	    default:
1068	        return;
1069	    }
1070	    f = f < 1 ? 1 : f > 65535 ? 65535 : f;
1071	    o[FMO_FREQ] = (u8)f;
1072	    o[FMO_FREQ + 1] = (u8)(f >> 8);
1073	    edit_done();
1074	}
