1146	/* The four knobs' MIDI offsets: a controller's 64 is none, 0 and 127 the
1147	 * ends of each knob's useful range (KNOB1 +-24 semitones, KNOB2 +-32
1148	 * glide steps, KNOB3 -64 to +32 level steps, KNOB4 +-7 feedback steps). */
1149	static const s8 knob_span[4][2] = { { -24, 24 }, { -32, 32 }, { -64, 32 }, { -7, 7 } };
1150	/* Since M8a, the macros' (macro_span, above), by the same rule. */
1151	
1152	static const s8 (*spans(void))[2]
1153	{
1154	    return knobs_mode ? knob_span : macro_span;
1155	}
1156	
1157	static int knob_offset(u32 k, u32 v)
1158	{
1159	    const s8 (*span)[2] = spans();
1160	
1161	    return v >= 64 ? (int)(v - 64) * span[k][1] / 63 : (int)(64 - v) * span[k][0] / 64;
1162	}
1163	
1164	/* Its inverse (M6b): the controller value whose offset is the panel
1165	 * knob's position p (held to the span), so a far end with its own knob at
1166	 * rest takes the same position: the v nearest 64 with knob_offset(k, v)
1167	 * == p (tests/test_midi_model.py checks every p against the model's). */
1168	static u32 knob_value(u32 k, int p)
1169	{
1170	    const s8 (*span)[2] = spans();
1171	    int lo = span[k][0], hi = span[k][1];
1172	
1173	    p = clamp(p, lo, hi);
1174	    return p >= 0 ? 64u + (u32)((p * 63 + hi - 1) / hi) : 64u - (u32)((-p * 64 - lo - 1) / -lo);
1175	}
