1177	/* A panel knob's move to MIDI out: as the first controller the map
1178	 * routes to it (DESIGN-NOTES.md, M6a), so the map's inverse; none if the
1179	 * map has none, and nothing while the value stays the same (a knob turned
1180	 * on past the end of its span). */
1181	static u8 knob_sent[4] = { 0xFF, 0xFF, 0xFF, 0xFF };
1182	
1183	static void knob_out(u32 k)
1184	{
1185	    u32 i, v = knob_value(k, knob_pos[k]);
1186	
1187	    if (v == knob_sent[k])
1188	        return;
1189	    for (i = 0; i < midi_settings.routes && i < MIDI_CC_ROUTES; i++)
1190	        if (midi_settings.cc[i].to == MIDI_TO_KNOB1 + k) {
1191	            midi_out_channel(MIDI_CC, midi_settings.cc[i].cc, v);
1192	            knob_sent[k] = (u8)v;
1193	            sb_midi_out.panel_ccs++;
1194	            return;
1195	        }
1196	}
