1198	/* Controllers back to rest (CC 121; a reset also): pitch bend, the mod
1199	 * wheel, expression and the pedal; the parameter number to none. */
1200	static void reset_controllers(void)
1201	{
1202	    bend = 0;
1203	    mod_wheel = 0;
1204	    expression = 127;
1205	    rpn = 0x3FFFu;
1206	    if (pedal)
1207	        pedal_up();
1208	}
