1210	/* Returns 1 if the controls must be read again. */
1211	static u32 controller(u32 cc, u32 v)
1212	{
1213	    u32 i;
1214	
1215	    switch (cc) {
1216	    case 6:                                 /* data entry: RPN 0, the bend range */
1217	        if (rpn == 0)
1218	            midi_settings.bend_range = (u8)(v > 24 ? 24 : v);
1219	        return 0;
1220	    case 100:
1221	        rpn = (rpn & 0x3F80u) | v;
1222	        return 0;
1223	    case 101:
1224	        rpn = (rpn & 0x7Fu) | v << 7;
1225	        return 0;
1226	    case 120:
1227	        sound_off();
1228	        return 0;
1229	    case 122:                               /* local control (M6b) */
1230	        midi_settings.local = v >= 64;
1231	        sb_work++;                          /* the screen shows it */
1232	        return 1;
1233	    case 121:
1234	        reset_controllers();
1235	        return 0;
1236	    case 123:
1237	    case 124:                               /* omni off, omni on: the channel stays */
1238	    case 125:
1239	        midi_notes_off();
1240	        return 0;
1241	    case 126:                               /* mono on, poly on */
1242	    case 127:
1243	        midi_notes_off();
1244	        all_off();
1245	        mono = cc == 126;
1246	        return 1;
1247	    }
1248	    for (i = 0; i < midi_settings.routes && i < MIDI_CC_ROUTES; i++) {
1249	        if (midi_settings.cc[i].cc != cc)
1250	            continue;
1251	        switch (midi_settings.cc[i].to) {
1252	        case MIDI_TO_MOD:
1253	            mod_wheel = v;
1254	            break;
1255	        case MIDI_TO_VOLUME:
1256	            volume = v;
1257	            break;
1258	        case MIDI_TO_EXPRESSION:
1259	            expression = v;
1260	            break;
1261	        case MIDI_TO_SUSTAIN:
1262	            if (v >= 64)
1263	                pedal = 1;
1264	            else if (pedal)
1265	                pedal_up();
1266	            break;
1267	        case MIDI_TO_KNOB1:
1268	        case MIDI_TO_KNOB2:
1269	        case MIDI_TO_KNOB3:
1270	        case MIDI_TO_KNOB4: {
1271	            u32 k = midi_settings.cc[i].to - MIDI_TO_KNOB1;
1272	            /* With the macros (M8a) the default map's two controllers
1273	             * named for M5's controls keep their meaning: 74, brightness,
1274	             * moves BRIGHT, and 5, the glide time, has no macro. */
1275	            if (!knobs_mode && cc == 5)
1276	                return 0;
1277	            if (!knobs_mode && cc == 74)
1278	                k = MACRO_BRIGHT;
1279	            midi_knob[k] = knob_offset(k, v);
1280	            return 1;
1281	        }
1282	        }
1283	        return 0;
1284	    }
1285	    return 0;
1286	}
