1288	/* One message; returns 1 if the controls must be read again. */
1289	static u32 midi_message(const struct midi_msg *m)
1290	{
1291	    u32 kind = m->status & 0xF0u, ch = m->status & 0x0Fu, again = 0;
1292	    int note = m->data[0];
1293	
1294	    if (m->status == MIDI_RESET) {
1295	        /* A system reset: as at power on, except the settings. */
1296	        midi_notes_off();
1297	        reset_controllers();
1298	        volume = 127;
1299	        midi_knob[0] = midi_knob[1] = midi_knob[2] = midi_knob[3] = 0;
1300	        return 1;
1301	    }
1302	    if (kind == 0xF0u)
1303	        return 0;                           /* realtime, common and SysEx: nothing to play */
1304	    if (midi_settings.channel != MIDI_OMNI && ch != midi_settings.channel - 1u) {
1305	        sb_midi.filtered++;
1306	        return 0;
1307	    }
1308	    switch (kind) {
1309	    case MIDI_NOTE_ON:
1310	        if (m->data[1]) {
1311	            sb_midi.notes_on++;
1312	            sb_midi.last_note_tick = sb_ticks();
1313	            note_press(note, m->data[1], HOLD_MIDI);
1314	            midi_screen_post(ch, note, m->data[1]);
1315	            break;
1316	        }
1317	        /* fall through: a note on at velocity 0 is a note off */
1318	    case MIDI_NOTE_OFF:
1319	        sb_midi.notes_off++;
1320	        note_release(note, HOLD_MIDI);
1321	        midi_screen_post(ch, note, 0);
1322	        break;
1323	    case MIDI_CC:
1324	        again = controller(m->data[0], m->data[1]);
1325	        break;
1326	    case MIDI_PROGRAM:
1327	        /* A program selects a test patch or (since M7) a user slot that
1328	         * holds a patch; any other is ignored. */
1329	        if (program_ok(m->data[0])) {
1330	            all_off();
1331	            select_patch(m->data[0]);
1332	            sb_midi.program = m->data[0];
1333	            again = 1;
1334	        }
1335	        break;
1336	    case MIDI_BEND:
1337	        /* 14 bits, 8192 the middle: +-bend_range semitones. */
1338	        bend = ((s32)(m->data[0] | (u32)m->data[1] << 7) - 8192) * midi_settings.bend_range / 2;
1339	        break;
1340	    default:
1341	        break;                              /* aftertouch: not used yet */
1342	    }
1343	    return again;
1344	}
