/* Back to the state at power on: no running status, no SysEx. */
void midi_parser_reset(void);

/* The notes MIDI plays, for the screen: the engine posts each note on and
 * off, main takes them (MIDI_SCREEN of them; when full, new ones are
 * dropped). A note is channel << 16 | note << 8 | velocity (0: off). */
#define MIDI_SCREEN 16u
void midi_screen_post(u32 channel, int note, u32 velocity);
int midi_screen_take(u32 *note);

/* --- Settings (stored as they are by M7) ------------------------------- */

/* Where a controller change goes (docs/DESIGN-NOTES.md, M6a, "The
 * controller map"). M8 adds targets and changes the map; MIDI learn will
 * write it. */
enum {
    MIDI_TO_NONE,
    MIDI_TO_MOD,          /* vibrato depth */
    MIDI_TO_VOLUME,
    MIDI_TO_EXPRESSION,
    MIDI_TO_SUSTAIN,
    MIDI_TO_KNOB1,        /* the engine's four controls, as KNOB1 to KNOB4 */
    MIDI_TO_KNOB2,
    MIDI_TO_KNOB3,
    MIDI_TO_KNOB4,
    MIDI_TARGETS
};

#define MIDI_SETTINGS_VERSION 3u   /* 2 since M6b: MIDI out's three settings; 3 since M8a: the knobs */
#define MIDI_OMNI             0u     /* channel: receive on every channel */
#define MIDI_CC_ROUTES        16u

struct midi_settings {
    u8 version;           /* MIDI_SETTINGS_VERSION */
    u8 channel;           /* MIDI_OMNI, or 1 to 16 */
    u8 bend_range;        /* semitones each way, 0 to 24 */
    u8 routes;            /* entries of cc[] in use */
    struct {
        u8 cc;            /* 0 to 119 */
        u8 to;            /* MIDI_TO_* */
    } cc[MIDI_CC_ROUTES];
    /* Since M6b (midi_out.h): */
    u8 out_channel;       /* the panel's messages go out on it: 1 to 16 */
    u8 thru;              /* 1: what MIDI in receives is sent out again */
    u8 local;             /* 1: the panel plays the engine; 0: MIDI out only */
    /* Since M8a (version 3; version 2's byte here was always 0): */
    u8 knobs;             /* 0: KNOB1 to KNOB4 are the macros; 1: direct (M5's controls) */
};
_Static_assert(sizeof(struct midi_settings) == 8 + 2 * MIDI_CC_ROUTES, "settings are bytes");

extern struct midi_settings midi_settings;
/* The defaults: omni, a bend of 2 semitones, the default map; since M6b,
 * out on channel 1, thru off, local control on. */
void midi_settings_default(struct midi_settings *s);

/* --- The MIDI record, after the engine's (firmware/app.ld) ------------ */
#define MIDI_MARKER 0x3649444Du   /* "MDI6" in memory order */
#define MIDI_LOG    64u
struct sb_midi_record {
    u32 marker;
    u32 bytes;          /* bytes received */
286:void midi_settings_default(struct midi_settings *s)
287-{
288-    u32 i, n = sizeof default_routes / sizeof default_routes[0];
289-
290-    s->version = MIDI_SETTINGS_VERSION;
291-    s->channel = MIDI_OMNI;
292-    s->bend_range = 2;
293-    s->routes = (u8)n;
294-    for (i = 0; i < MIDI_CC_ROUTES; i++) {
295-        s->cc[i].cc = i < n ? default_routes[i][0] : 0;
296-        s->cc[i].to = i < n ? default_routes[i][1] : MIDI_TO_NONE;
297-    }
298-    s->out_channel = 1;
299-    s->thru = 0;
300-    s->local = 1;
301-    s->knobs = 0;
302-}
