101	/* --- What the screen shows: worked out from the engine's state -------- */
102	
103	static struct fm_ui ui;                 /* the state as last taken */
104	static u8 prog[FM_PATCH_BYTES];         /* the program's bytes, then */
105	static u32 program, algorithm, mono, octave, user_used, ui_seen = 0xFFFFFFFFu;
106	static s32 knob_value[4];
107	
108	/* The state when it holds still (the engine may change it meanwhile). */
109	static void take(void)
110	{
111	    const u8 *p;
112	    u32 s, i;
113	
114	    do {
115	        s = fm_ui.seq;
116	        ui.screen = fm_ui.screen;
117	        ui.op = fm_ui.op;
118	        ui.page = fm_ui.page;
119	        ui.row = fm_ui.row;
120	        ui.env = fm_ui.env;
121	        ui.confirm = fm_ui.confirm;
122	        ui.knobs = fm_ui.knobs;
123	        p = fm_program_bytes();
124	        for (i = 0; i < FM_PATCH_BYTES; i++)
125	            prog[i] = p[i];
126	        program = sb_fm.patch;
127	        algorithm = sb_fm.algorithm;
128	        mono = sb_fm.mono;
129	        octave = sb_audio.engine[SYNTH_OCTAVE];
130	        user_used = fm_user_used();
