132	            knob_value[0] = sb_fm.pitch_knob;
133	            knob_value[1] = (s32)sb_fm.glide;
134	            knob_value[2] = sb_fm.depth;
135	            knob_value[3] = sb_fm.feedback;
136	        } else {
137	            for (i = 0; i < 4; i++)
138	                knob_value[i] = sb_ui.macro[i];
139	        }
140	    } while (s != fm_ui.seq);
141	    ui.seq = s;
142	}
