144	/* The header: "001 NAME" ("U01 NAME" for a user slot), the mode, the
145	 * octave ("O+1"). */
146	static char head_text[3][17], head_drawn[3][17];
147	
148	static void head_work(void)
149	{
150	    u32 n = 0, i, p = program, u = p - FM_PATCHES + 1u;
151	
152	    if (p < FM_PATCHES) {
153	        n = put(head_text[0], 0, "00");
154	        head_text[0][n++] = (char)('1' + p);
155	    } else {
156	        head_text[0][n++] = 'U';
157	        head_text[0][n++] = (char)('0' + u / 10);
158	        head_text[0][n++] = (char)('0' + u % 10);
159	    }
160	    head_text[0][n++] = ' ';
161	    for (i = 0; i < 12 && prog[FMP_NAME + i]; i++)
162	        head_text[0][n++] = (char)prog[FMP_NAME + i];
163	    pad(head_text[0], n, 16);
164	    n = put(head_text[1], 0, mono ? "MONO" : "POLY");
165	    head_text[1][n] = 0;
166	    n = put(head_text[2], 0, (s32)octave ? "O" : "O+");
167	    n = decimal(head_text[2], n, (int)(s32)octave, 1);
168	    pad(head_text[2], n, 3);
169	}
170	
171	/* The bottom strip: four names and four values. */
172	static char strip_name[4][11], strip_value[4][6];
173	static char strip_name_drawn[4][11], strip_value_drawn[4][6];
174	
175	static void strip_set(u32 k, const char *name, int v, int sign)
176	{
177	    u32 n = put(strip_name[k], 0, name);
178	
179	    pad(strip_name[k], n, 10);
180	    n = decimal(strip_value[k], 0, v, sign);
181	    pad(strip_value[k], n, 5);
182	}
183	
184	static void strip_text(u32 k, const char *name, const char *value)
185	{
186	    u32 n = put(strip_name[k], 0, name);
187	
188	    pad(strip_name[k], n, 10);
189	    n = put(strip_value[k], 0, value);
190	    pad(strip_value[k], n, 5);
191	}
