197	/* The operator view's strip (M8a part 3): the selected operator's values
198	 * on the page SELECT chose. */
199	static void strip_edit(void)
200	{
201	    const u8 *o = op_bytes(ui.op);
202	    char b[12];
203	    u32 n;
204	
205	    if (ui.page == 0) {
206	        n = freq_text(b, 0, o);
207	        if (o[FMO_MODE])
208	            n -= 2;   /* the strip's 5 characters: no "Hz" */
209	        b[n] = 0;
