211	        strip_set(1, "LEVEL", o[FMO_LEVEL], 0);
212	        strip_set(2, "DETUNE", s8v(o[FMO_DETUNE]), 1);
213	        strip_set(3, "VELO", o[FMO_VELOCITY], 0);
214	    } else if (ui.page == 1) {
215	        strip_text(0, "MODE", o[FMO_MODE] ? "fixed" : "ratio");
216	        n = freq_text(b, 0, o);
217	        if (o[FMO_MODE])
218	            n -= 2;
219	        b[n] = 0;
220	        strip_text(1, "COARSE", b);
221	        strip_text(2, "FINE", b);
222	        strip_text(3, "", "");
223	    } else {
224	        strip_set(0, "PEAK", o[FMO_ENV_LEVEL], 0);
225	        strip_set(1, "D1 LEVEL", o[FMO_ENV_LEVEL + 1], 0);
226	        strip_set(2, "HOLD", o[FMO_ENV_LEVEL + 2], 0);
227	        strip_text(3, "", "");
228	    }
229	}
