231	/* The settings' strip (M8a part 6): KNOB1 changes the row's value. */
232	static void strip_settings(void)
233	{
234	    static const char *const names[SETTING_ROWS] = {
235	        "IN CH", "OUT CH", "THRU", "LOCAL", "BEND", "KNOBS", "STORE", "RESET",
236	    };
237	    const struct midi_settings *m = &midi_settings;
238	    char b[8];
239	    u32 n = 0, r = ui.row < SETTING_ROWS ? ui.row : 0, k;
240	
241	    switch (r) {
242	    case 0:
243	        n = m->channel == MIDI_OMNI ? put(b, 0, "omni") : decimal(b, 0, m->channel, 0);
244	        break;
245	    case 1:
246	        n = decimal(b, 0, m->out_channel, 0);
247	        break;
248	    case 2:
249	        n = put(b, 0, m->thru ? "on" : "off");
250	        break;
251	    case 3:
252	        n = put(b, 0, m->local ? "on" : "off");
253	        break;
254	    case 4:
255	        n = decimal(b, 0, m->bend_range, 0);
256	        break;
257	    case 5:
258	        n = put(b, 0, m->knobs ? "dir" : "macro");
259	        break;
260	    case 7:
261	        n = put(b, 0, ui.confirm ? "SAVE?" : "");
262	        break;
263	    }
264	    b[n] = 0;
265	    strip_text(0, r == 6 ? "" : names[r], r == 6 ? "" : b);
266	    for (k = 1; k < 4; k++)
267	        strip_text(k, "", "");
268	}
