270	/* The envelope view's strip (M8a part 4). */
271	static void strip_env(void)
272	{
273	    static const char *const rates[4] = { "ATTACK", "DECAY1", "DECAY2", "RELEASE" };
274	    static const char *const levels[3] = { "PEAK", "D1 LEVEL", "HOLD" };
275	    static const char *const prates[4] = { "RATE1", "RATE2", "RATE3", "DEPTH" };
276	    static const char *const plevels[4] = { "P0", "P1", "P2", "P3" };
277	    const u8 *o = op_bytes(ui.op);
278	    u32 k;
279	
280	    for (k = 0; k < 4; k++) {
281	        if (ui.env == 2 && k)
282	            strip_text(k, "", "");
283	        else if (ui.env == 2)
284	            strip_set(0, "GLIDE", prog[FMP_GLIDE], 0);
285	        else if (ui.env == 1 && !ui.page)
286	            strip_set(k, prates[k], k < 3 ? prog[FMP_PITCH_RATE + k] : s8v(prog[FMP_PITCH_DEPTH]), k == 3);
287	        else if (ui.env == 1)
288	            strip_set(k, plevels[k], s8v(prog[FMP_PITCH_LEVEL + k]), 1);
289	        else if (!ui.page)
290	            strip_set(k, rates[k], o[FMO_RATE + k], 0);
291	        else if (k < 3)
292	            strip_set(k, levels[k], o[FMO_ENV_LEVEL + k], 0);
293	        else
294	            strip_text(k, "", "");
295	    }
