298	static void strip_work(void)
299	{
300	    static const char *const macros[4] = { "BRIGHT", "COLOR", "SHAPE", "MOTION" };
301	    u32 k;
302	
303	    if (ui.screen == UI_EDIT) {
304	        strip_edit();
305	        return;
306	    }
307	    if (ui.screen == UI_ENV) {
308	        strip_env();
309	        return;
310	    }
311	    if (ui.screen == UI_SETTINGS) {
312	        strip_settings();
313	        return;
314	    }
315	    if (ui.knobs) {
316	        /* The setting "Knobs: direct": M5's controls, pitch, glide,
317	         * modulation depth, feedback. */
318	        strip_set(0, "PITCH", knob_value[0], 1);
319	        strip_set(1, "GLIDE", knob_value[1], 0);
320	        strip_set(2, "DEPTH", knob_value[2], 1);
321	        strip_set(3, "FDBK", knob_value[3], 1);
322	        return;
323	    }
324	    for (k = 0; k < 4; k++)
325	        strip_set(k, macros[k], knob_value[k], k != 3);
326	}
