328	/* The body's signature: when it changes, the body is drawn again. */
329	static u32 body_sig, body_sig_marked;
330	
331	static u32 mix(u32 h, u32 v)
332	{
333	    return (h ^ v) * 16777619u;
334	}
335	
336	static u32 body_work(void)
337	{
338	    u32 h = 2166136261u, i;
339	
340	    h = mix(h, ui.screen);
341	    h = mix(h, ui.op);
342	    h = mix(h, ui.page);
343	    h = mix(h, ui.row);
344	    h = mix(h, ui.env);
345	    h = mix(h, ui.confirm);
346	    h = mix(h, ui.knobs);
347	    h = mix(h, algorithm);
348	    h = mix(h, user_used);
349	    h = mix(h, midi_settings.local);
350	    /* What a body shows of the program: the operator view's values are
351	     * on its info line and strip, so an edit redraws only those. */
352	    if (ui.screen == UI_PATCH)
353	        h = mix(h, prog[FMP_FEEDBACK]);
354	    /* The envelope view's graph is its own part (graph_work). */
355	    if (ui.screen == UI_SETTINGS) {
356	        const u8 *s = (const u8 *)&midi_settings;
357	        for (i = 0; i < sizeof midi_settings; i++)
358	            h = mix(h, s[i]);
359	    }
360	    return h;
361	}
362	
363	/* --- Drawing ------------------------------------------------------------ */
