            text(k * COLUMN_W + 2, STRIP_Y + 5, strip_name[k], WHITE, 1);
        if (names || !same(strip_value[k], strip_value_drawn[k]))
            text(k * COLUMN_W, STRIP_Y + 18, strip_value[k], YELLOW, 2);
        copy_text(strip_name_drawn[k], strip_name[k]);
