1033	#define BAND_H      (BODY_H / BANDS)
1034	#define ITEM_HEAD   (1u << 0)
1035	#define ITEM_CLEAR0 1u            /* bits 1 to 4: the body's bands cleared */
1036	#define ITEM_BODY   (1u << 5)
