1042	#define ITEM_GRAPH  (3u << 14)    /* the envelope view's graph (M8a part 4): cleared in two halves, */
1043	#define ITEM_GRAPH_DRAW (1u << 16)  /* drawn, */
1044	#define ITEM_GRAPH_SEND (1u << 17)  /* and sent */
1045	#define ITEM_SPEC   (1u << 18)    /* the patch view's spectrum (M8a part 5): the transform, */
1046	#define ITEM_SPEC2  (1u << 19)    /* in three parts, */
1047	#define ITEM_SPEC3  (1u << 20)
1048	#define ITEM_SPEC_DRAW (1u << 21) /* the bars drawn and sent */
1049	/* The parts that send to the panel (the others only draw or compute). */
1050	#define ITEM_SENDS (ITEM_HEAD | (((1u << BANDS) - 1u) << ITEM_SEND0) | ITEM_LINE | ITEM_STRIP | ITEM_INFO \
1051	                    | ITEM_LIVE | ITEM_GRAPH_SEND | ITEM_SPEC_DRAW)
