1091	static void spectrum_part(u32 step)
1092	{
1093	    u32 t = sb_now(), j, moved = 0, top = 0;
1094	
1095	    if (step == 0) {
1096	        spec_ticks = 0;
1097	        if (!spectrum_start()) {
1098	            for (j = 0; j < SPEC_BARS; j++)
1099	                bars_new[j] = 0;
1100	            sb_ui.spec_silent++;
1101	            goto bars;
1102	        }
1103	        spectrum_stages(0, 4);
1104	        spec_ticks += sb_now() - t;
1105	        dirty |= ITEM_SPEC2;
1106	        return;
1107	    }
1108	    if (step == 1) {
1109	        spectrum_stages(4, 7);
1110	        spec_ticks += sb_now() - t;
1111	        dirty |= ITEM_SPEC3;
1112	        return;
1113	    }
1114	    spectrum_bars(bars_new, SPEC_H);
1115	    spec_ticks += sb_now() - t;
1116	    sb_ui.spec_updates++;
1117	    if (spec_ticks > sb_ui.spec_max)
1118	        sb_ui.spec_max = spec_ticks;
1119	bars:
1120	    for (j = 0; j < SPEC_BARS; j++) {
1121	        moved |= bars_new[j] != bars_drawn[j];
1122	        if (bars_new[j] > bars_new[top])
1123	            top = j;
1124	    }
