1168	/* Starts a frame once FRAME_MS have passed since the last began, and
1169	 * draws what is marked until it is all drawn or this block's drawing
1170	 * time is spent; otherwise asks the tick to wake main again: for the
1171	 * frame, or for the rest of it a millisecond on. */
1172	static void draw_frame(void)
1173	{
1174	    u32 beats = sb_beacon.beats;
1175	
1176	    if (!in_frame) {
1177	        if (beats - frame_beat < FRAME_MS) {
1178	            wake_at(frame_beat + FRAME_MS);
1179	            return;
1180	        }
1181	        in_frame = 1;
1182	        frame_beat = beats;
1183	        sb_ui.frames++;
1184	    }
1185	    while (dirty) {
1186	        u32 bit = 0, t, d;
1187	
1188	        if (sb_audio.blocks != draw_block) {
1189	            draw_block = sb_audio.blocks;
1190	            spent = 0;
1191	        } else if (spent >= DRAW_TICKS) {
1192	            wake_at(beats + 1);
1193	            return;
1194	        }
1195	        while (!(dirty >> bit & 1))
1196	            bit++;
1197	        /* A part that sends waits for the bus to be free, in the next
1198	         * block, rather than in lcd_wait (the spectrum's 40 rows take
1199	         * about 10 ms of it). */
1200	        if ((1u << bit) & ITEM_SENDS && lcd_busy()) {
1201	            wake_at(beats + 1);
1202	            return;
1203	        }
1204	        dirty &= ~(1u << bit);
1205	        t = sb_now();
1206	        draw_item(bit);
1207	        d = sb_now() - t;
1208	        spent += d;
1209	        sb_ui.items++;
1210	        if (d > sb_ui.item_max) {
1211	            sb_ui.item_max = d;
1212	            sb_ui.item_max_part = bit;
1213	        }
1214	        if (spent > sb_ui.block_max)
1215	            sb_ui.block_max = spent;
1216	        if (spent > DRAW_TICKS && d < spent)
1217	            sb_ui.over++;
1218	    }
1219	    in_frame = 0;
1220	}
