{
    char b[24];
    u32 n;

    draw_algorithm(algorithm - 1u, 4, BODY_Y + 6, 120, 110, FM_OPS);
    n = put(b, 0, "ALG ");
    n = decimal(b, n, (int)algorithm, 0);
